// ---- tee/src/memory/records.ts
// records — the pure half of the Walrus Memory record format (TOTAL_RECALL.md §1): serialize, parse,
// bucket. No Node imports: this file is also bundled for the browser (tistu/js/vendor/memory.js) so the
// Memory Time Machine replays memories with the SAME code the server runs. `format.ts` re-exports it and
// adds the Node-only pieces (hashed namespaces).
//
// One fact per memory, plain text, `TYPE v1 | key=value | …`. Plain text keeps the memory semantically
// recallable by the relayer's embedding search; the versioned key=value body keeps it machine-parseable.
// The parser ignores unknown keys and missing keys default to `na`, so records written by older code stay valid.

export const RECORD_TYPES = [
  'CONVICTION', 'OUTCOME', 'CALIBRATION', 'LESSON', 'REASON', 'VETTING', 'USER', 'COUNCIL', 'PAYMENT',
  // N2 Ulysses Rules: a promise to your future self, its retirement, and every time you broke one
  'RULE', 'RULE_REMOVED', 'OVERRIDE',
]         ;

                                           

// ---------------------------------------------------------------- write side
const clean = (v         )         => {
  if (v === null || v === undefined || (typeof v === 'number' && !Number.isFinite(v))) return 'na';
  const s = String(v);
  return s.replace(/[|\n\r]/g, ' ').trim() || 'na';
};
export const p2 = (x                           ) => (x == null || !Number.isFinite(x) ? 'na' : x.toFixed(2));
export const p3 = (x                           ) => (x == null || !Number.isFinite(x) ? 'na' : x.toFixed(3));
export const signed2 = (x                           ) =>
  (x == null || !Number.isFinite(x) ? 'na' : (x >= 0 ? '+' : '') + x.toFixed(2));

/** Serialize a record. `text` fields are quoted so they may contain spaces. */
export function formatRecord(type            , fields                     )         {
  const parts = fields.map(([k, v]) => {
    if (k === 'text') return `text="${clean(v).replace(/"/g, "'")}"`;
    return `${k}=${clean(v)}`;
  });
  return `${type} v1 | ${parts.join(' | ')}`;
}

// ---------------------------------------------------------------- read side
/** Parse one memory line. Returns null for anything that isn't a HELIX v1+ record. */
export function parseRecord(text        , meta                                            = {})                   {
  if (typeof text !== 'string') return null;
  const t = text.trim();
  const head = /^([A-Z_]+)\s+v(\d+)\s*\|/.exec(t);
  if (!head) return null;
  const type = head[1]              ;
  if (!(RECORD_TYPES                     ).includes(type)) return null;
  const body = t.slice(head[0].length);
  const f                         = {};
  // key=value pairs separated by `|`; text="..." may contain anything but a double quote
  const re = /\s*([a-z_][a-z0-9_]*)\s*=\s*("([^"]*)"|[^|]*)\s*(\||$)/gi;
  let m                        ;
  while ((m = re.exec(body))) {
    if (m[0] === '') { re.lastIndex++; continue; }
    f[m[1].toLowerCase()] = (m[3] !== undefined ? m[3] : m[2]).trim();
  }
  return { type, version: Number(head[2]), f, text: t, blob_id: meta.blob_id, created_at: meta.created_at };
}

export function num(r                       , k        )                {
  const v = r?.f[k];
  if (v == null || v === 'na' || v === '') return null;
  const n = Number(v.replace(/,/g, ''));
  return Number.isFinite(n) ? n : null;
}
export function str(r                       , k        )                {
  const v = r?.f[k];
  return v == null || v === 'na' || v === '' ? null : v;
}

/** When a record happened, in seconds: its own `ts`, else the relayer's created_at, else 0. */
export function recordTs(r           )         {
  const t = num(r, 'ts');
  if (t != null) return t;
  const c = r.created_at ? Date.parse(r.created_at) : NaN;
  return Number.isFinite(c) ? Math.floor(c / 1000) : 0;
}

// ---------------------------------------------------------------- buckets

export const dirWord = (direction        )          => (direction >= 20 ? 'up' : direction <= -20 ? 'down' : 'neutral');
export const confBand = (conf01        ) => (conf01 < 0.4 ? 'low' : conf01 < 0.7 ? 'mid' : 'high');
export const volWord = (volView        ) => (volView < 50 ? 'calm' : 'choppy');
export const bucketKey = (dir        , conf01        , vol        ) => `${dir}/${confBand(conf01)}/${vol}`;
/** The asset a record is about. Records written before multi-asset (P5) carry none and are BTC. */
export const assetOf = (r                       )         => (str(r, 'asset') ?? 'BTC').toUpperCase();
/** Calibration bucket. BTC keeps its original keys (`up/high/choppy`); other assets are scoped (`ETH:up/high/choppy`). */
export function bucketOfConviction(r           )                {
  const dir = str(r, 'dir'), conf = num(r, 'conf'), vol = str(r, 'vol');
  if (!dir || conf == null || !vol) return null;
  const a = assetOf(r), k = bucketKey(dir, conf, vol);
  return a === 'BTC' ? k : `${a}:${k}`;
}

/** "you" voice: confidence 0–100 mapped to a win probability in [0.5, 0.95]. */
export const pYou = (confidence        ) => 0.5 + 0.45 * Math.max(0, Math.min(100, confidence)) / 100;

// ---- tee/src/memory/calibration.ts
// calibration — who was right, in which setup (TOTAL_RECALL.md §1 "Calibration math").
// Pure functions; every number the UI shows about memory comes from here.
//
//  • posterior win rate per bucket: Beta(2,2) prior → (wins + 2) / (n + 4)
//  • Brier per voice: mean((p − o)²), o ∈ {0,1}; lower is better
//  • over-confidence gap: mean(p_you) − posterior
//  • blended probability: weights ∝ 1 / max(brier, 0.05); falls back to the market when n < 3
//  • suggested commit: fractional Kelly (¼) at the remembered posterior, as a share of the
//    Kelly the user's own stated probability implies, capped at the user's commit
//  • structure bias: ranges vs directional posterior in the same regime, n ≥ 3 each, gap > 0.15

export const MIN_N = 3;
export const KELLY_FRACTION = 0.25;
export const MIN_ORDER_USDC = 1.5;   // Predict refuses premiums under 1 USDC; fees on top

const mean = (xs          ) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : null);
export const brierOf = (pairs                    ) => mean(pairs.map(([p, o]) => (p - o) ** 2));
export const posteriorOf = (wins        , n        ) => (wins + 2) / (n + 4);

export function bucketStats(rows              )              {
  const n = rows.length;
  const wins = rows.filter((r) => r.won === 1).length;
  const crowd = rows.filter((r) => r.p_crowd != null);
  const cncl = rows.filter((r) => r.p_council != null);
  const mpy = mean(rows.map((r) => r.p_you));
  const post = posteriorOf(wins, n);
  return {
    n, wins,
    realized: n ? wins / n : null,
    posterior: post,
    mean_p_you: mpy,
    gap_you: mpy == null ? null : mpy - post,
    brier: {
      you: brierOf(rows.map((r) => [r.p_you, r.won])),
      market: brierOf(rows.filter((r) => r.p_mkt != null).map((r) => [r.p_mkt          , r.won])),
      helix: brierOf(rows.filter((r) => r.p_hlx != null).map((r) => [r.p_hlx          , r.won])),
      crowd: brierOf(crowd.map((r) => [r.p_crowd          , r.won])),
      council: brierOf(cncl.map((r) => [r.p_council          , r.won])),
    },
    n_crowd: crowd.length,
    n_council: cncl.length,
    pnl: rows.reduce((a, r) => a + (r.payoff ?? 0), 0),
  };
}

/** Weighted blend of the voices' current probabilities by inverse remembered Brier. */
export function blendedProbability(
  now                                           , stats                    ,
)                                                                                                {
  if (!stats || stats.n < MIN_N) return { p: now.market ?? null, weights: { market: 1 }, basis: 'market' };
  const raw                                     = {};
  for (const v of ['you', 'market', 'helix', 'crowd', 'council']               ) {
    const b = stats.brier[v];
    const p = now[v];
    if (p == null || b == null) continue;
    if (v === 'crowd' && stats.n_crowd < MIN_N) continue;
    if (v === 'council' && (stats.n_council ?? 0) < MIN_N) continue;
    raw[v] = 1 / Math.max(b, 0.05);
  }
  const tot = Object.values(raw).reduce((a, b) => a + (b          ), 0);
  if (!tot) return { p: now.market ?? null, weights: { market: 1 }, basis: 'market' };
  const weights                                     = {};
  let p = 0;
  for (const [v, w] of Object.entries(raw)                         ) {
    weights[v] = w / tot;
    p += (w / tot) * (now[v]          );
  }
  return { p, weights, basis: 'memory' };
}

/** Full Kelly fraction for a bet paying net odds b at win probability p (never negative). */
export const kelly = (p        , b        ) => (b > 0 ? Math.max(0, (p * b - (1 - p)) / b) : 0);

/** Net payoff odds of a Predict contract bought at `pricePerContract` (pays $1). */
export const oddsFromPrice = (pricePerContract        ) =>
  pricePerContract > 0 && pricePerContract < 1 ? (1 - pricePerContract) / pricePerContract : 0;

                              
                              

/**
 * Suggested commit: scale the user's commit by how much Kelly shrinks when the stated
 * probability is replaced by the remembered posterior. Never above the user's commit,
 * never below the smallest order Predict accepts; with n < 3 it is the user's commit.
 */
export function suggestCommit(commit        , p_you        , stats                    , b        )                   {
  const f_you = KELLY_FRACTION * kelly(p_you, b);
  if (!stats || stats.n < MIN_N) return { suggested: commit, basis: 'no_history', f_you, f_memory: f_you };
  const f_memory = KELLY_FRACTION * kelly(stats.posterior, b);
  let s        ;
  if (f_you <= 0) s = commit;                       // no stated edge to scale from
  else s = commit * Math.min(1, f_memory / f_you);
  s = Math.max(Math.min(MIN_ORDER_USDC, commit), Math.min(commit, s));
  return { suggested: Math.round(s * 100) / 100, basis: 'kelly', f_you, f_memory };
}

export const RANGEISH = new Set(['range', 'bracketed_range']);

/** Prefer a structure family when its remembered posterior beats the other by > 0.15. */
export function structureBias(rowsInRegime              )

  {
  const rng = rowsInRegime.filter((r) => RANGEISH.has(r.structure));
  const dir = rowsInRegime.filter((r) => r.structure === 'directional');
  const pr = rng.length ? posteriorOf(rng.filter((r) => r.won).length, rng.length) : null;
  const pd = dir.length ? posteriorOf(dir.filter((r) => r.won).length, dir.length) : null;
  let prefer                                 = null;
  if (rng.length >= MIN_N && dir.length >= MIN_N && pr != null && pd != null) {
    if (pr - pd > 0.15) prefer = 'range';
    else if (pd - pr > 0.15) prefer = 'directional';
  }
  return { prefer, post_range: pr, post_dir: pd, n_range: rng.length, n_dir: dir.length };
}

/** The voice with the lowest remembered Brier (needs n ≥ 3; crowd needs its own n ≥ 3). */
export function bestVoice(stats             )                   {
  if (stats.n < MIN_N) return null;
  let best                   = null, bv = Infinity;
  for (const v of ['you', 'market', 'helix', 'crowd', 'council']               ) {
    const b = stats.brier[v];
    if (b == null || (v === 'crowd' && stats.n_crowd < MIN_N) || (v === 'council' && (stats.n_council ?? 0) < MIN_N)) continue;
    if (b < bv) { bv = b; best = v; }
  }
  return best;
}

export const VOICE_LABEL                            = {
  you: 'your own confidence', market: 'the Predict market', helix: "HELIX's regime model", crowd: 'the Polymarket crowd',
  council: 'the HELIX Council',
};

/** A plain-language lesson, only when the bucket has n ≥ 3 and a clear pattern. */
export function lessonFor(bucket        , stats             , bias                                         )                {
  if (stats.n < MIN_N) return null;
  const bits           = [];
  if (stats.gap_you != null && Math.abs(stats.gap_you) >= 0.15) {
    bits.push(stats.gap_you > 0
      ? `Won ${stats.wins}/${stats.n} here; stated confidence runs ~${Math.round(stats.gap_you * 100)} points hot. Size down.`
      : `Won ${stats.wins}/${stats.n} here; stated confidence runs ~${Math.round(-stats.gap_you * 100)} points cold. You are better than you think.`);
  }
  if (bias?.prefer === 'range') bits.push(`Ranges won more than directional bets in this regime (${Math.round((bias.post_range ?? 0) * 100)}% vs ${Math.round((bias.post_dir ?? 0) * 100)}%). Prefer ranges.`);
  if (bias?.prefer === 'directional') bits.push(`Directional bets beat ranges in this regime (${Math.round((bias.post_dir ?? 0) * 100)}% vs ${Math.round((bias.post_range ?? 0) * 100)}%).`);
  const bv = bestVoice(stats);
  if (bv && bv !== 'you' && stats.brier.you != null && stats.brier[bv] != null && stats.brier.you - (stats.brier[bv]          ) >= 0.05) {
    bits.push(`${VOICE_LABEL[bv][0].toUpperCase()}${VOICE_LABEL[bv].slice(1)} has been closer than you (Brier ${(stats.brier[bv]          ).toFixed(2)} vs ${stats.brier.you.toFixed(2)}).`);
  }
  return bits.length ? `${bucket}: ${bits.join(' ')}` : null;
}

/**
 * F4 Beat the Market (NEXT_BIG.md §5): today's settled calls, each won by the voice that put the most
 * probability on what actually happened (smallest (p − outcome)²). The Council joins only on rows where it
 * was live, so every compared voice saw the same window. Ties give each tied voice the point.
 */
export function beatTheMarket(rows              , now = Date.now()) {
  const dayStart = Math.floor(now / 86_400_000) * 86_400_000;
  const today = rows.filter((r) => r.ts * 1000 >= dayStart && r.ts * 1000 <= now && r.p_mkt != null);
  const withCouncil = today.filter((r) => r.p_council != null);
  const threeWay = withCouncil.length > 0;
  const use = threeWay ? withCouncil : today;
  const score                         = threeWay ? { you: 0, market: 0, council: 0 } : { you: 0, market: 0 };
  for (const r of use) {
    const err                         = { you: (r.p_you - r.won) ** 2, market: ((r.p_mkt          ) - r.won) ** 2 };
    if (threeWay) err.council = ((r.p_council          ) - r.won) ** 2;
    const best = Math.min(...Object.values(err));
    for (const [k, e] of Object.entries(err)) if (Math.abs(e - best) < 1e-12) score[k]++;
  }
  return { day: new Date(dayStart).toISOString().slice(0, 10), n: use.length, mode: threeWay ? 'you · market · council' : 'you · market', score };
}

// ---- tee/src/memory/rows.ts
// rows — from recalled memories to settled rows, and the Memory Time Machine replay (N1).
// Pure: no Node imports. Bundled for the browser with records.ts and calibration.ts, so the scrubber on the
// Memory page re-computes calibration "as of <time>" with exactly the code the server runs for the live page.

/** CONVICTION ⋈ OUTCOME (WIN/LOSS) by tx. BTC rows need every voice; ETH/SUI have no Predict market (P5). */
export function settledRows(recs             )               {
  const outcomes = new Map                   ();
  for (const r of recs) if (r.type === 'OUTCOME' && str(r, 'tx')) outcomes.set(str(r, 'tx') , r);
  const rows               = [];
  for (const c of recs) {
    if (c.type !== 'CONVICTION') continue;
    const tx = str(c, 'tx'); const o = tx ? outcomes.get(tx) : undefined;
    const res = str(o, 'result');
    if (!o || (res !== 'WIN' && res !== 'LOSS')) continue;
    const pyou = num(c, 'p_you'), pm = num(c, 'p_mkt'), ph = num(c, 'p_hlx');
    if (pyou == null || (assetOf(c) === 'BTC' && (pm == null || ph == null))) continue;
    rows.push({
      tx: tx , won: res === 'WIN' ? 1 : 0, p_you: pyou, p_mkt: pm, p_hlx: ph, p_crowd: num(c, 'p_crowd'), p_council: num(c, 'p_council'),
      structure: str(c, 'structure') ?? 'directional', regime: str(c, 'regime'),
      commit: num(c, 'commit') ?? 0, payoff: num(o, 'payoff'), ts: num(c, 'ts') ?? 0,
    });
  }
  return rows;
}

export const bucketOfRow = (recs             , tx        )                => {
  const c = recs.find((r) => r.type === 'CONVICTION' && str(r, 'tx') === tx);
  return c ? bucketOfConviction(c) : null;
};

/** Settled rows grouped by calibration bucket. */
export function bucketRows(recs             , rows              )                            {
  const buckets = new Map                      ();
  for (const r of rows) { const b = bucketOfRow(recs, r.tx); if (b) (buckets.get(b) ?? buckets.set(b, []).get(b) ).push(r); }
  return buckets;
}

// ---------------------------------------------------------------- time machine
/** The setup the scrubber answers "what would memory suggest?" for (the Canvas conviction, or the latest one remembered). */

export const recordsUpTo = (recs             , at        ) => (at === Infinity ? recs : recs.filter((r) => recordTs(r) <= at));

/** Calibration as of `at`, from the memories that existed then. At `Infinity` this is exactly the live page's state. */
export function replayState(recs             , at        , setup               = null)              {
  const then = recordsUpTo(recs, at);
  const rows = settledRows(then);
  const overall = bucketStats(rows);
  const buckets = [...bucketRows(then, rows)].map(([bucket, rs]) => ({ bucket, stats: bucketStats(rs) }));
  const lessons = then.filter((r) => r.type === 'LESSON').map((r) => ({ ts: recordTs(r), bucket: str(r, 'bucket'), text: str(r, 'text'), blob_id: r.blob_id }));
  let suggestion                            = null;
  if (setup) {
    const st = buckets.find((b) => b.bucket === setup.bucket)?.stats ?? null;
    const b = setup.price != null ? oddsFromPrice(setup.price) : 1;
    const s = suggestCommit(setup.commit, setup.p_you, st, b);
    suggestion = { ...s, bucket: setup.bucket, n: st?.n ?? 0, posterior: st && st.n >= MIN_N ? st.posterior : null, gap_you: st?.gap_you ?? null };
  }
  return { at, count: then.length, overall, buckets, lessons, suggestion };
}

/** The setup of the latest remembered conviction (what the Memory page replays when the Canvas has none). */
export function latestSetup(recs             )               {
  const c = [...recs].reverse().find((r) => r.type === 'CONVICTION' && bucketOfConviction(r));
  if (!c) return null;
  const conf = num(c, 'conf') ?? 0.5;
  return { bucket: bucketOfConviction(c) , commit: num(c, 'commit') ?? 0, p_you: num(c, 'p_you') ?? pYou(conf * 100), price: num(c, 'price') };
}

/**
 * Moments worth a tick on the scrubber track: the first settled outcome, the first bucket to reach n ≥ 3
 * (memory starts changing the product), the first LESSON, and the biggest Council weight shift.
 */
export function keyMoments(recs             , councilHistory                                                    = [])              {
  const out              = [];
  const sorted = [...recs].sort((a, b) => recordTs(a) - recordTs(b));
  const firstOutcome = sorted.find((r) => r.type === 'OUTCOME' && (str(r, 'result') === 'WIN' || str(r, 'result') === 'LOSS'));
  if (firstOutcome) out.push({ ts: recordTs(firstOutcome), kind: 'first_outcome', label: 'first settled call' });
  const firstLesson = sorted.find((r) => r.type === 'LESSON');
  if (firstLesson) out.push({ ts: recordTs(firstLesson), kind: 'first_lesson', label: 'first lesson' });
  const seen = new Map                ();
  for (const r of sorted) {
    if (r.type !== 'OUTCOME') continue;
    const b = str(r, 'tx') ? bucketOfRow(sorted, str(r, 'tx') ) : null;
    if (!b) continue;
    const n = (seen.get(b) ?? 0) + 1; seen.set(b, n);
    if (n === MIN_N) { out.push({ ts: recordTs(r), kind: 'first_n3', label: `${b} reaches n=${MIN_N}` }); break; }
  }
  let best                   = null, bestD = 0;
  for (let i = 1; i < councilHistory.length; i++) {
    const a = councilHistory[i - 1].weights, b = councilHistory[i].weights;
    const d = Object.keys({ ...a, ...b }).reduce((s, k) => s + Math.abs((b[k] ?? 0) - (a[k] ?? 0)), 0);
    if (d > bestD) { bestD = d; best = { ts: councilHistory[i].ts, kind: 'weights_shift', label: 'biggest Council re-weighting' }; }
  }
  if (best && bestD > 1e-6) out.push(best);
  return out.sort((a, b) => a.ts - b.ts);
}
